@@ -1,17 +1,55 @@
 export type DiffOp = { op: "keep" | "del" | "add"; line: string };
 export type DiffStats = { kept: number; deleted: number; added: number };

+const PREFIX: Record<DiffOp["op"], string> = { keep: "  ", del: "- ", add: "+ " };
+
 /** Edit script that turns `a` into `b`. See README.md for the exact rules. */
 export function diffLines(a: string[], b: string[]): DiffOp[] {
-  throw new Error("not implemented");
+  const n = a.length;
+  const m = b.length;
+
+  // common[i][j] is the length of the longest common subsequence of a.slice(i) and b.slice(j).
+  const common: number[][] = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0));
+  for (let i = n - 1; i >= 0; i--) {
+    for (let j = m - 1; j >= 0; j--) {
+      common[i][j] =
+        a[i] === b[j] ? common[i + 1][j + 1] + 1 : Math.max(common[i + 1][j], common[i][j + 1]);
+    }
+  }
+
+  const ops: DiffOp[] = [];
+  let i = 0;
+  let j = 0;
+  while (i < n && j < m) {
+    if (a[i] === b[j]) {
+      ops.push({ op: "keep", line: a[i] });
+      i++;
+      j++;
+    } else if (common[i + 1][j] === common[i][j]) {
+      ops.push({ op: "del", line: a[i] });
+      i++;
+    } else {
+      ops.push({ op: "add", line: b[j] });
+      j++;
+    }
+  }
+  for (; i < n; i++) ops.push({ op: "del", line: a[i] });
+  for (; j < m; j++) ops.push({ op: "add", line: b[j] });
+  return ops;
 }

